 {const x=X(430);R(x-4,30,88,96,'#3a2a1a');const g=ctx.createLinearGradient(0,34,0,122);g.addColorStop(0,'#04060e');g.addColorStop(1,'#1a1030');ctx.fillStyle=g;ctx.fillRect(x,34,80,88);for(let i=0;i<10;i++)R(x+((i*23)%76),36+((i*17)%80),1,1,'#e8f0ff');ctx.strokeStyle='#b07aff';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x+60,40);ctx.lineTo(x+54,70);ctx.lineTo(x+64,100);ctx.stroke();ctx.lineWidth=1;c3Lamp(x+60,70,50,'rgba(176,122,255,.4)',.8);R(x+38,34,4,88,'#3a2a1a');R(x,76,80,4,'#3a2a1a')}
 // 심장시계
 {const x=X(280),y=100,rot=rt!=null&&rt>11400?t*1.2:0;pcirc(x,y,62,'#2a2030');pcirc(x,y,56,'#3a3040');for(let i=0;i<12;i++){const a=i*TAU/12;R(x+Math.cos(a)*48-2,y+Math.sin(a)*48-2,4,4,'#d4ae4a')}
  for(let k=0;k<3;k++){const gx=x+[-22,20,0][k],gy=y+[-8,10,22][k],r=[16,13,10][k];for(let i=0;i<10;i++){const a=i*TAU/10+rot*(k%2?-1:1);R(gx+Math.cos(a)*(r+2)-1,gy+Math.sin(a)*(r+2)-1,3,3,'#8a7a5a')}pcirc(gx,gy,r,'#5a4a3a');pcirc(gx,gy,r*.4,'#2a2030')}
  pcirc(x,y,10,'#1a1420');pcirc(x,y,6,rt!=null&&rt>11400?'#b07aff':'#4a3a5a');R(x-2,y-36,4,26,'#1a1420');R(x-6,y-40,12,8,'#1a1420');
  for(let i=0;i<5;i++){R(X(200+i*40),160,6,20,'#4a4a54')}}
 // 레버
 {const x=X(380),dn=rt==null||rt>11410;R(x-8,150,16,30,'#3a3a44');ctx.save();ctx.translate(x,152);ctx.rotate(dn?.9:-.6);R(-2,-34,4,34,'#6a6a74');pcirc(0,-36,5,'#8a3a2a');ctx.restore()}
